namespace sv_ccdf0a10c17742b19a811ab4bda4de7d.Services;

/// <summary>
/// Scoped (per-circuit) service that tracks low-stock alert counts.
/// Components subscribe to <see cref="OnAlertCountChanged"/> to receive
/// updates regardless of their position in the component tree.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Raised whenever <see cref="RefreshAlertCountAsync"/> produces a new value.
    /// All subscribed components are notified — not just the one that triggered the poll.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query that returns the number of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with a random result (0–15).
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest alert count for <paramref name="warehouseId"/>,
    /// stores it, and notifies all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }
}

