@using sv_ccdf0a10c17742b19a811ab4bda4de7d.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Selected warehouse: <strong>@WarehouseState.CurrentWarehouseId</strong>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text fs-2">
            <span class="badge @(AlertService.CurrentAlertCount > 0 ? "bg-danger" : "bg-success") fs-4">
                @AlertService.CurrentAlertCount
            </span>
            <span class="ms-2 text-muted fs-6">
                item(s) below minimum stock level
            </span>
        </p>
        @if (_lastRefresh.HasValue)
        {
            <p class="text-muted small mb-0">
                Last checked: @_lastRefresh.Value.ToString("HH:mm:ss") — polling every 10 s
            </p>
        }
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private DateTime? _lastRefresh;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Immediately fetch once, then start the polling loop.
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            _lastRefresh = DateTime.Now;
            StateHasChanged();

            _cts = new CancellationTokenSource();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            _lastRefresh = DateTime.Now;
            await InvokeAsync(StateHasChanged);
        }
    }

    private void HandleWarehouseChanged()
    {
        // When the warehouse changes, do an immediate refresh.
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
    }

    private async Task HandleAlertCountChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
    }
}

